<?php
declare(strict_types=1);
// Tack's registration reservation and invite checks, adapted to Wavehaus roles
// and one-use self-hosted proofs. Credentials are never saved in access requests.
function access_email(mixed $value): ?string {
    $email=input_text($value,'Email',254);if(!$email)return null;if(!filter_var($email,FILTER_VALIDATE_EMAIL))fail('validation','Use a valid email address, or leave it empty.');$domain=strtolower(substr(strrchr($email,'@'),1));foreach(['10minutemail.com','guerrillamail.com','guerrillamail.net','mailinator.com','sharklasers.com','yopmail.com','yopmail.fr','getnada.com','temp-mail.org','tempmail.com']as $item)if($domain===$item||str_ends_with($domain,'.'.$item))fail('validation','Use a lasting address, or leave email empty.');return $email;
}
function access_invite(PDO $db,mixed $code): array {
    if(!is_string($code)||!preg_match('/^WH-[0-9A-HJKMNP-TV-Z]{4}-[0-9A-HJKMNP-TV-Z]{4}$/D',strtoupper($code)))fail('invalid_invite','Use a valid invitation.',403);$invite=query_one($db,"SELECT i.*,u.role AS creator_role FROM invites i JOIN users u ON u.id=i.created_by WHERE i.code=? AND i.uses_left>0 AND(i.expires_at IS NULL OR i.expires_at>?) AND u.status='active'",[strtoupper($code),now_ms()]);if(!$invite)fail('invalid_invite','This invitation is unavailable or expired.',403);return $invite;
}
function access_link(string $code): string {return (getenv('WAVEHAUS_DEV')==='1'?'http':'https').'://'.$_SERVER['HTTP_HOST'].app_base().'join/'.$code;}
function access_code(): string {$value=substr(ulid(),10,8);return 'WH-'.substr($value,0,4).'-'.substr($value,4);}
function access_challenge(PDO $db): never {
    rate_limit($db,'challenge',30,900,client_ip(settings($db)));$salt=token(16);$t=now_ms();$expires=$t+300000;$difficulty=(int)(settings($db)['pow_difficulty']??18);$signature=hash_hmac('sha256',$salt.'|'.$difficulty.'|'.$expires.'|'.$t,app_secret());execute($db,"DELETE FROM rate_limits WHERE (key LIKE 'challenge:%' OR key LIKE 'pow:%') AND window_start<?",[$t-600000]);execute($db,'INSERT INTO rate_limits(key,window_start,count,locked_until) VALUES(?,?,?,?)',['challenge:'.$salt,$t,$difficulty,$expires]);reply(['algorithm'=>'SHA-256','salt'=>$salt,'difficulty'=>$difficulty,'expires'=>$expires,'t'=>$t,'signature'=>$signature]);
}
function access_proof(PDO $db,array $input): string {
    $pow=$input['pow']??null;if(!is_array($pow)||!is_string($pow['salt']??null)||!preg_match('/^[A-Za-z0-9_-]{22}$/D',$pow['salt'])||!is_int($pow['nonce']??null)||$pow['nonce']<0||$pow['nonce']>9007199254740991||!is_string($pow['signature']??null)||($input['hp']??$input['website']??'')!==''||($input['website']??'')!=='')fail('proof_required','Complete the account verification.',403);
    $row=query_one($db,'SELECT window_start,count,locked_until FROM rate_limits WHERE key=?',['challenge:'.$pow['salt']]);if(!$row||(int)$row['locked_until']<now_ms()||($input['t']??null)!==(int)$row['window_start']||now_ms()-(int)$row['window_start']<3000)fail('proof_expired','Complete a fresh account verification after filling in the form.',403);$signature=hash_hmac('sha256',$pow['salt'].'|'.$row['count'].'|'.$row['locked_until'].'|'.$row['window_start'],app_secret());if(!hash_equals($signature,$pow['signature']))fail('proof_required','Complete the account verification.',403);$bits=0;foreach(unpack('C*',hash('sha256',$pow['salt'].$pow['nonce'],true))as $byte){if($byte===0){$bits+=8;continue;}for($mask=128;($byte&$mask)===0;$mask>>=1)$bits++;break;}if($bits<(int)$row['count'])fail('proof_required','Complete the account verification.',403);return 'pow:'.$pow['salt'];
}
function registration_routes(PDO $db,string $path,string $method): bool {
    if($path==='/api/auth/challenge'&&$method==='GET')access_challenge($db);if(!in_array($path,['/api/auth/register','/api/auth/request-access'],true)||$method!=='POST')return false;$input=body();$register=$path==='/api/auth/register';rate_limit($db,$register?'register':'request-access',3,$register?3600:86400,client_ip(settings($db)));$proof=access_proof($db,$input);
    $hash=$register&&isset($input['password'])?password_hash(validate_password($input['password']),password_algorithm()):null;
    try{$result=transaction($db,function()use($db,$input,$register,$proof,$hash){
        if(query_one($db,'SELECT key FROM rate_limits WHERE key=?',[$proof]))fail('proof_used','Complete a fresh verification and try again.',409);$cfg=settings($db);$raw=$register?($input['inviteCode']??null):($input['referralCode']??null);$invite=$raw?access_invite($db,$raw):null;$adminInvite=$invite&&in_array($invite['creator_role'],['owner','admin'],true);$mode=$cfg['registration_mode'];if($mode==='closed'&&!$adminInvite||$mode==='invite'&&!$invite||$register&&$mode==='request'&&!$invite||!$register&&$mode!=='request'&&!$invite)fail('registration_closed',$mode==='request'?'Request access or use an invitation.':'An invitation is required.',403);execute($db,'INSERT INTO rate_limits(key,window_start,count) VALUES(?,?,1)',[$proof,now_ms()]);
        $pending=!$register||($invite&&!$adminInvite&&($cfg['referrals_need_approval']??false)===true);if($pending){$id=ulid();$name=input_text($register?($input['username']??null):($input['name']??null),'Name',100,true);$contact=input_text($input['contact']??null,'Contact',254);if($contact&&str_contains($contact,'@')&&!str_contains($contact,' '))access_email($contact);execute($db,'INSERT INTO access_requests(id,name,contact,note,referral_code,ip_hash,created_at) VALUES(?,?,?,?,?,?,?)',[$id,$name,$contact,input_text($input['note']??null,'Note',2000),$invite['code']??null,hash_hmac('sha256',client_ip($cfg),app_secret()),now_ms()]);if($invite)execute($db,'UPDATE invites SET uses_left=uses_left-1 WHERE id=?',[$invite['id']]);return ['pending'=>true,'requestId'=>$id];}
        $name=validate_username($input['username']??null,true);validate_password($input['password']??null);$email=access_email($input['email']??null);$label=device_label($input['deviceLabel']??null);if(query_one($db,'SELECT id FROM users WHERE username=?',[$name]))fail('username_taken','That username is already taken.',409);$role=$invite['role']??$cfg['default_role'];if(!in_array($role,['admin','uploader','listener'],true)||$role==='admin'&&!$adminInvite)fail('forbidden','Use an invitation for a valid member role.',403);$id=ulid();execute($db,'INSERT INTO users(id,username,display_name,email,password_hash,role,quota_bytes,invites_left,invited_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',[$id,$name,input_text($input['displayName']??null,'Display name',100)??$name,$email,$hash,$role,$cfg['member_quota_bytes']??null,$cfg['invites_per_member']??3,$invite['referrer_id']??$invite['created_by']??null,now_ms()]);if($invite)execute($db,'UPDATE invites SET uses_left=uses_left-1 WHERE id=?',[$invite['id']]);return ['user'=>public_user(query_one($db,'SELECT * FROM users WHERE id=?',[$id])),'recoveryCodes'=>recovery_codes($db,$id),'session'=>mint_session($db,$id,$label)];
    });}catch(PDOException $error){if(str_contains($error->getMessage(),'UNIQUE'))fail('username_taken','That username is already taken.',409);throw $error;}
    if(isset($result['session'])){session_cookie($result['session']['raw']);unset($result['session']);}reply($result,201);
}
function access_member_fields(array $input): array {
    if(array_diff(array_keys($input),['role','status','quotaBytes','invitesLeft']))fail('validation','Choose role, quota, status or referral allowance.');$fields=[];foreach(['role'=>['admin','uploader','listener'],'status'=>['active','disabled']]as $key=>$values)if(array_key_exists($key,$input)){if(!in_array($input[$key],$values,true))fail('validation','Choose a valid '.$key.'.');$fields[$key]=$input[$key];}foreach(['quotaBytes'=>['quota_bytes',9007199254740991],'invitesLeft'=>['invites_left',10000]]as $key=>[$column,$maximum])if(array_key_exists($key,$input)){$value=$input[$key];if($key==='quotaBytes'&&$value===null)$fields[$column]=null;else{if(!is_int($value)||$value<0||$value>$maximum)fail('validation','Use a valid quota or referral allowance.');$fields[$column]=$value;}}if(!$fields)fail('validation','Choose a member setting to change.');return $fields;
}
function access_routes(PDO $db,array $auth,string $path,string $method): bool {
    $uid=$auth['user']['id'];$admin=in_array($auth['user']['role'],['owner','admin'],true);
    if($path==='/api/invites'&&$method==='GET'){$rows=query_all($db,'SELECT i.*,u.display_name AS created_by_name FROM invites i JOIN users u ON u.id=i.created_by WHERE '.($admin?'1':'i.created_by=?').' ORDER BY i.created_at DESC LIMIT 2000',$admin?[]:[$uid]);foreach($rows as &$row)$row['url']=access_link($row['code']);reply(['items'=>$rows,'nextCursor'=>null]);}
    if($path==='/api/invites'&&$method==='POST'){$input=body();$result=transaction($db,function()use($db,$auth,$uid,$input){$actor=query_one($db,"SELECT * FROM users WHERE id=? AND status='active'",[$uid]);$admin=$actor&&in_array($actor['role'],['owner','admin'],true);$cfg=settings($db);if(!$actor||!$admin&&($actor['invites_left']<1||$cfg['registration_mode']==='closed'))fail('forbidden','You have no referrals available.',403);$role=$admin?($input['role']??$cfg['default_role']):$cfg['default_role'];$uses=$admin?($input['uses']??1):1;$days=$admin?($input['expiresDays']??7):7;if(!in_array($role,['admin','uploader','listener'],true)||$role==='admin'&&$actor['role']!=='owner'||!is_int($uses)||$uses<1||$uses>100||!is_int($days)||$days<1||$days>30)fail('validation','Choose a valid role, use count and expiry.');$id=ulid();$code=access_code();$expires=now_ms()+$days*86400000;execute($db,'INSERT INTO invites(id,code,created_by,role,uses_left,expires_at,created_at) VALUES(?,?,?,?,?,?,?)',[$id,$code,$uid,$role,$uses,$expires,now_ms()]);if(!$admin)execute($db,'UPDATE users SET invites_left=invites_left-1 WHERE id=?',[$uid]);return ['id'=>$id,'code'=>$code,'url'=>access_link($code),'expiresAt'=>$expires];});reply($result,201);}
    if(preg_match('~^/api/invites/([0-9A-HJKMNP-TV-Z]{26})$~',$path,$match)&&$method==='DELETE'){execute($db,'UPDATE invites SET uses_left=0 WHERE id=?'.($admin?'':' AND created_by=?'),$admin?[$match[1]]:[$match[1],$uid]);reply(['ok'=>true]);}
    if(!str_starts_with($path,'/api/admin/'))return false;require_admin($auth);
    if($path==='/api/admin/users'&&$method==='GET')reply(['items'=>query_all($db,'SELECT u.id,u.username,u.display_name,u.role,u.status,u.quota_bytes,u.used_bytes,u.invites_left,u.invited_by,u.created_at,p.display_name AS invited_by_name FROM users u LEFT JOIN users p ON p.id=u.invited_by ORDER BY u.created_at LIMIT 2000'),'nextCursor'=>null]);
    if(preg_match('~^/api/admin/users/([0-9A-HJKMNP-TV-Z]{26})$~',$path,$match)&&$method==='PATCH'){$fields=access_member_fields(body());transaction($db,function()use($db,$auth,$match,$fields,$uid){$actor=query_one($db,"SELECT role FROM users WHERE id=? AND status='active'",[$uid]);$target=query_one($db,'SELECT * FROM users WHERE id=?',[$match[1]]);if(!$target)fail('not_found','Member not found.',404);if(!$actor||!in_array($actor['role'],['owner','admin'],true)||$target['role']==='owner'||$target['id']===$uid||$actor['role']==='admin'&&($target['role']==='admin'||($fields['role']??null)==='admin'))fail('forbidden','Only the owner can manage admins. Transfer ownership to change the owner.',403);execute($db,'UPDATE users SET '.implode(',',array_map(fn($key)=>$key.'=?',array_keys($fields))).' WHERE id=?',[...array_values($fields),$target['id']]);if(($fields['status']??null)==='disabled')foreach(['sessions','pairing_codes']as $table)execute($db,'DELETE FROM '.$table.' WHERE user_id=?',[$target['id']]);});reply(['ok'=>true]);}
    if($path==='/api/admin/requests'&&$method==='GET')reply(['items'=>query_all($db,'SELECT r.*,i.code AS invite_code FROM access_requests r LEFT JOIN invites i ON i.id=r.invite_id ORDER BY r.created_at DESC LIMIT 2000'),'nextCursor'=>null]);
    if(preg_match('~^/api/admin/requests/([0-9A-HJKMNP-TV-Z]{26})/(approve|deny)$~',$path,$match)&&$method==='POST'){$result=transaction($db,function()use($db,$auth,$match,$uid){$actor=query_one($db,"SELECT role FROM users WHERE id=? AND status='active'",[$uid]);if(!$actor||!in_array($actor['role'],['owner','admin'],true))fail('forbidden','Only an admin can decide requests.',403);$item=query_one($db,'SELECT * FROM access_requests WHERE id=?',[$match[1]]);if(!$item)fail('not_found','Request not found.',404);if($item['status']!=='pending')fail('conflict','This request has already been decided.',409);$approve=$match[2]==='approve';$id=null;$code=null;if($approve){$id=ulid();$code=access_code();$referrer=$item['referral_code']?query_one($db,'SELECT created_by FROM invites WHERE code=?',[$item['referral_code']]):null;execute($db,'INSERT INTO invites(id,code,created_by,role,uses_left,expires_at,created_at,referrer_id) VALUES(?,?,?,?,1,?,?,?)',[$id,$code,$uid,settings($db)['default_role'],now_ms()+7*86400000,now_ms(),$referrer['created_by']??null]);}execute($db,'UPDATE access_requests SET status=?,decided_by=?,decided_at=?,invite_id=? WHERE id=?',[$approve?'approved':'denied',$uid,now_ms(),$id,$item['id']]);return $approve?['ok'=>true,'code'=>$code,'url'=>access_link($code)]:['ok'=>true];});reply($result);}
    if($path==='/api/admin/ownership'&&$method==='POST'){$input=body();transaction($db,function()use($db,$auth,$uid,$input){$owner=query_one($db,"SELECT * FROM users WHERE id=? AND role='owner' AND status='active'",[$uid]);if(!$owner)fail('forbidden','Only the owner can transfer ownership.',403);if(!password_verify((string)($input['password']??''),$owner['password_hash']))fail('invalid_credentials','Username or password is incorrect.',401);$target=query_one($db,"SELECT id FROM users WHERE id=? AND status='active'",[$input['userId']??'']);if(!$target||$target['id']===$uid)fail('validation','Choose another active member.');execute($db,"UPDATE users SET role='admin' WHERE id=?",[$uid]);execute($db,"UPDATE users SET role='owner',quota_bytes=NULL WHERE id=?",[$target['id']]);});reply(['ok'=>true]);}
    return false;
}
